//! The server stage: what the production encoders would have queued for the
//! recorded client, rebuilt from frozen truth.
//!
//! Two streams are regenerated by production code:
//!
//! - the game snapshot: `snapshot_builder::build_recipient_snapshot` (the
//!   function the live `broadcast_snapshot` calls) + `protocol::
//!   encode_server_packet`, fed from `world.bin`, `snapshot-inputs.jsonl`
//!   and `snapshot-baseline.json`;
//! - the city stream: `ChunkStreamEncoder` resumed from the capture's
//!   checkpoint and driven through the same call sequence as
//!   `server/src/city.rs::feed_encoder` / `CityRuntime::step` and
//!   `MatchState::tick_city` (ingest -> topology -> baseline -> hash; on a
//!   send tick `encode_send` then `client_datagrams` per camera, in the live
//!   call order; bootstraps where the live server sent them).
//!
//! Every other packet the client received (welcome, roster, body metadata,
//! shot results, match stats, meteor launches, pings...) is not a netcode
//! optimisation target and is passed through: its recorded bytes, at the
//! time the send log says the server queued it.

use std::collections::{BTreeMap, HashMap};

use serde::Serialize;
use vibe_land_destruction::encoder::{ChunkStreamEncoder, EncoderConfig};
use vibe_land_destruction::netlab::tape::TapeReader;
use vibe_land_destruction::types::Camera;
use vibe_land_shared::constants::{
    FLAG_MELEEING, PKT_CITY_BASELINE, PKT_CITY_BOOTSTRAP, PKT_CITY_CHUNKS, PKT_CITY_DEBRIS,
    PKT_CITY_TOPOLOGY, PKT_PING, PKT_SNAPSHOT, PKT_SNAPSHOT_V2,
};

use crate::bundle::Bundle;
use crate::protocol::{
    encode_server_packet, make_net_dynamic_body_state, make_net_player_state, NetVehicleState,
};
use crate::snapshot_builder::{
    self, BodyMeta, RecipientInput, RecipientInterest, SnapshotConfig, SnapshotWorld,
};
use crate::vltape::{CHANNEL_RTT, CHANNEL_WT_DATAGRAM};

pub const PKT_CITY_TOPO_HASH: u8 = vibe_land_destruction::wire::PKT_CITY_TOPO_HASH;
pub const PKT_CITY_STRUCTURE_BOOTSTRAP: u8 = vibe_land_destruction::wire::PKT_CITY_STRUCTURE_BOOTSTRAP;
/// Mirrors `server/src/city.rs` `TOPO_HASH_INTERVAL_TICKS`.
pub const TOPO_HASH_INTERVAL_TICKS: u32 = 120;

/// The lane production queues a kind on (`main.rs::wants_unreliable_delivery`).
pub fn wants_unreliable_delivery(kind: u8) -> bool {
    kind == PKT_SNAPSHOT
        || kind == PKT_SNAPSHOT_V2
        || kind == PKT_PING
        || kind == PKT_CITY_CHUNKS
        || kind == PKT_CITY_DEBRIS
}

pub fn is_snapshot_kind(kind: u8) -> bool {
    kind == PKT_SNAPSHOT || kind == PKT_SNAPSHOT_V2
}

/// Kinds the city encoder (wire v2) produces.
pub fn is_city_encoder_kind(kind: u8) -> bool {
    matches!(kind, PKT_CITY_CHUNKS | PKT_CITY_TOPOLOGY | PKT_CITY_BASELINE | PKT_CITY_BOOTSTRAP)
        || kind == PKT_CITY_TOPO_HASH
        || kind == PKT_CITY_STRUCTURE_BOOTSTRAP
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum Lane {
    Reliable,
    Datagram,
}

impl Lane {
    pub fn of_kind(kind: u8) -> Self {
        if wants_unreliable_delivery(kind) {
            Lane::Datagram
        } else {
            Lane::Reliable
        }
    }

    pub fn name(self) -> &'static str {
        match self {
            Lane::Reliable => "reliable",
            Lane::Datagram => "datagram",
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum Origin {
    /// Regenerated by production encoder code in the lab.
    Lab,
    /// Recorded bytes, queued when the send log says.
    Pass,
    /// Recorded bytes from before the server capture began (no send-log
    /// record): queued at arrival minus the lane's typical latency.
    PrePass,
}

#[derive(Clone, Debug)]
pub struct Outgoing {
    /// When the server queued it, on the tape clock.
    pub depart_ms: f64,
    pub seq: u64,
    pub tick: u32,
    pub lane: Lane,
    pub kind: u8,
    pub bytes: Vec<u8>,
    pub origin: Origin,
    /// Pass-through: the recorded tape packet. Lab: the live send record it
    /// corresponds to (same tick, kind and ordinal), if any.
    pub tape_index: Option<usize>,
    pub live_record: Option<usize>,
    /// Lab: the n-th packet of this kind this tick.
    pub ordinal: u32,
}

/// How the server's time runs in the lab.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum Pace {
    /// Ticks at the wall times the live server reached them (its slowdowns
    /// included), packets at their phase inside the tick.
    Recorded,
    /// Ticks every 1/sim_hz exactly: the netcode in isolation from server
    /// runtime performance.
    Ideal,
}

/// City encoder knobs, applied over the checkpoint's (i.e. production's)
/// effective configuration.
#[derive(Clone, Debug, Default, PartialEq, Serialize, serde::Deserialize)]
pub struct CityKnobs {
    pub send_hz: Option<u32>,
    pub ceiling_bytes: Option<usize>,
    pub error_budget_px: Option<f32>,
    pub burst_capacity_sends: Option<u32>,
    pub burst_max_multiple: Option<u32>,
    pub baseline_interval_ticks: Option<u32>,
    pub proximity_m: Option<f32>,
}

impl CityKnobs {
    pub fn apply(&self, config: &mut EncoderConfig) {
        if let Some(hz) = self.send_hz {
            config.send_interval_ticks = (config.sim_hz / hz.max(1)).max(1);
        }
        if let Some(bytes) = self.ceiling_bytes {
            config.client_ceiling_bytes = if bytes == 0 { usize::MAX } else { bytes };
        }
        if let Some(px) = self.error_budget_px {
            config.error_budget_px = px;
        }
        if let Some(value) = self.burst_capacity_sends {
            config.burst_capacity_sends = value;
        }
        if let Some(value) = self.burst_max_multiple {
            config.burst_max_multiple = value;
        }
        if let Some(value) = self.baseline_interval_ticks {
            config.baseline_interval_ticks = value;
        }
        if let Some(value) = self.proximity_m {
            config.interest.proximity_meters = value;
        }
    }

    pub fn is_default(&self) -> bool {
        *self == Self::default()
    }
}

#[derive(Clone, Debug)]
pub struct StreamConfig {
    pub pace: Pace,
    pub snapshot: SnapshotConfig,
    /// Snapshot every N sim ticks (None: as the live match did).
    pub snapshot_interval_ticks: Option<u32>,
    pub city: CityKnobs,
    /// Replay the structure repairs the live server sent (open loop, S6).
    /// `false` (`--knob lab.recorded_repairs=0`) withholds them, so the
    /// client's own counters say whether its ledger stays in sync without
    /// them and how many repairs it would ask for.
    pub recorded_repairs: bool,
}

impl Default for StreamConfig {
    fn default() -> Self {
        Self {
            pace: Pace::Recorded,
            snapshot: SnapshotConfig::PRODUCTION,
            snapshot_interval_ticks: None,
            city: CityKnobs::default(),
            recorded_repairs: true,
        }
    }
}

#[derive(Clone, Debug, Default, Serialize, serde::Deserialize)]
pub struct StreamStats {
    pub first_tick: u32,
    pub last_tick: u32,
    pub snapshot_ticks: u32,
    pub snapshot_interval_ticks: u32,
    pub strict_snapshots: bool,
    pub snapshot_inputs: String,
    pub snapshot_interest_start: String,
    pub city_first_tick: Option<u32>,
    pub city_encoder_start: String,
    pub city_send_interval_ticks: u32,
    pub city_ceiling_bytes: usize,
    pub city_bootstraps: u32,
    pub city_structure_bootstraps_passed_through: u32,
    /// Recorded structure repairs withheld (`lab.recorded_repairs=0`).
    #[serde(default)]
    pub city_structure_bootstraps_withheld: u32,
    pub passthrough_by_kind: BTreeMap<u8, u32>,
    pub prepass_by_kind: BTreeMap<u8, u32>,
    pub lab_by_kind: BTreeMap<u8, u32>,
    /// Snapshot selection outcome totals (what the budget left out).
    pub snapshot_selection: BTreeMap<String, u64>,
    /// City selection outcome totals for this client.
    pub city_selection: BTreeMap<String, u64>,
}

/// Recorded tape packets joined to the send-log records that produced them,
/// by (CRC32, length) in send order -- the join `session_bundle.py` makes.
pub struct Join {
    /// tape packet index -> send record index
    pub tape_to_record: HashMap<usize, usize>,
    pub record_to_tape: HashMap<usize, usize>,
    /// Our player's delivered-or-not records keyed by (tick, kind), in queue order.
    pub records_by_tick_kind: HashMap<(u32, u8), Vec<usize>>,
    /// Per lane, median (arrival - queued) of joined packets, ms.
    pub median_latency_ms: HashMap<Lane, f64>,
}

pub fn join(bundle: &Bundle) -> Join {
    let player = bundle.player;
    let mut mine: Vec<usize> = (0..bundle.sendlog.len())
        .filter(|&i| bundle.sendlog[i].player == player)
        .collect();
    mine.sort_by_key(|&i| (bundle.sendlog[i].sent_us, i));
    let mut by_key: HashMap<(u32, u32), Vec<usize>> = HashMap::new();
    for &i in &mine {
        let record = &bundle.sendlog[i];
        if record.outcome <= 1 {
            by_key.entry((record.crc32, record.size)).or_default().push(i);
        }
    }
    let mut cursor: HashMap<(u32, u32), usize> = HashMap::new();
    let mut tape_to_record = HashMap::new();
    let mut record_to_tape = HashMap::new();
    let mut latencies: HashMap<Lane, Vec<f64>> = HashMap::new();
    for (index, packet) in bundle.tape.packets.iter().enumerate() {
        if packet.is_prelude() || packet.base_channel() == CHANNEL_RTT {
            continue;
        }
        let key = (crc32fast::hash(&packet.bytes), packet.bytes.len() as u32);
        let Some(queue) = by_key.get(&key) else {
            continue;
        };
        let at = cursor.entry(key).or_insert(0);
        if let Some(&record_index) = queue.get(*at) {
            *at += 1;
            tape_to_record.insert(index, record_index);
            record_to_tape.insert(record_index, index);
            let record = &bundle.sendlog[record_index];
            let queued = if record.queued_us == crate::send_log::QUEUED_BEFORE_CAPTURE {
                record.sent_us
            } else {
                record.queued_us
            };
            let lane = if packet.base_channel() == CHANNEL_WT_DATAGRAM {
                Lane::Datagram
            } else {
                Lane::Reliable
            };
            latencies
                .entry(lane)
                .or_default()
                .push(packet.t_ms - bundle.server_to_tape_ms(queued));
        }
    }
    let mut records_by_tick_kind: HashMap<(u32, u8), Vec<usize>> = HashMap::new();
    let mut by_queue = mine.clone();
    by_queue.sort_by_key(|&i| {
        let record = &bundle.sendlog[i];
        (record.tick, record.queued_us.min(record.sent_us), i)
    });
    for i in by_queue {
        let record = &bundle.sendlog[i];
        records_by_tick_kind.entry((record.tick, record.kind)).or_default().push(i);
    }
    let median_latency_ms = latencies
        .into_iter()
        .map(|(lane, mut values)| {
            values.sort_by(|a, b| a.total_cmp(b));
            (lane, values[values.len() / 2])
        })
        .collect();
    Join { tape_to_record, record_to_tape, records_by_tick_kind, median_latency_ms }
}

/// Tick phase times on the tape clock: (start, city done, snapshot done, end).
struct Clock<'a> {
    bundle: &'a Bundle,
    pace: Pace,
    first_tick: u32,
    first_start_ms: f64,
    tick_ms: f64,
}

impl<'a> Clock<'a> {
    fn new(bundle: &'a Bundle, pace: Pace) -> Self {
        let first_tick = bundle.first_tick();
        let tick_ms = 1000.0 / bundle.sim_hz as f64;
        let first_start_ms = bundle
            .timings
            .get(&first_tick)
            .map(|t| bundle.server_to_tape_ms(t.mono_us) - f64::from(t.total_ms))
            .unwrap_or(0.0);
        Self { bundle, pace, first_tick, first_start_ms, tick_ms }
    }

    fn recorded(&self, tick: u32) -> Option<(f64, f64, f64, f64)> {
        let t = self.bundle.timings.get(&tick)?;
        let end = self.bundle.server_to_tape_ms(t.mono_us);
        let start = end - f64::from(t.total_ms);
        let city = (start
            + f64::from(t.player_sim_ms + t.vehicle_ms + t.dynamics_ms + t.hitscan_ms + t.city_ms))
            .min(end);
        let snapshot = (city + f64::from(t.snapshot_ms)).min(end);
        Some((start, city, snapshot, end))
    }

    fn ideal_start(&self, tick: u32) -> f64 {
        self.first_start_ms + (f64::from(tick) - f64::from(self.first_tick)) * self.tick_ms
    }

    fn phases(&self, tick: u32) -> (f64, f64, f64, f64) {
        match self.pace {
            Pace::Recorded => self.recorded(tick).unwrap_or_else(|| {
                let s = self.ideal_start(tick);
                (s, s, s, s + self.tick_ms)
            }),
            Pace::Ideal => {
                let s = self.ideal_start(tick);
                (s, s, s, s)
            }
        }
    }

    /// A pass-through packet's recorded queue time, re-timed for the pace.
    fn retime(&self, tick: u32, recorded_ms: f64) -> f64 {
        match self.pace {
            Pace::Recorded => recorded_ms,
            Pace::Ideal => match self.recorded(tick) {
                Some((start, _, _, _)) => {
                    self.ideal_start(tick) + (recorded_ms - start).clamp(0.0, self.tick_ms * 0.99)
                }
                None => recorded_ms,
            },
        }
    }
}

struct Emitter {
    out: Vec<Outgoing>,
    seq: u64,
    ordinals: HashMap<(u32, u8), u32>,
}

impl Emitter {
    fn lab(&mut self, depart_ms: f64, tick: u32, bytes: Vec<u8>, join: &Join) {
        let kind = bytes[0];
        let ordinal = self.ordinals.entry((tick, kind)).or_insert(0);
        let live_record = join
            .records_by_tick_kind
            .get(&(tick, kind))
            .and_then(|records| records.get(*ordinal as usize).copied());
        self.out.push(Outgoing {
            depart_ms,
            seq: self.seq,
            tick,
            lane: Lane::of_kind(kind),
            kind,
            bytes,
            origin: Origin::Lab,
            tape_index: live_record.and_then(|record| join.record_to_tape.get(&record).copied()),
            live_record,
            ordinal: *ordinal,
        });
        *ordinal += 1;
        self.seq += 1;
    }
}

/// Reconstructs a vehicle's wire state from its truth (which the capture
/// wrote by converting the arena's wire units back to floats; this inverts
/// that exactly, see the round-trip test).
pub fn vehicle_wire_state(v: &crate::session_capture::VehicleTruth) -> NetVehicleState {
    use crate::protocol::{f32_to_snorm16, meters_to_mm};
    let cms = |mps: f32| (mps * 100.0).round() as i16;
    let mrads = |rads: f32| (rads * 1000.0).round() as i16;
    NetVehicleState {
        id: v.id,
        vehicle_type: v.vehicle_type,
        flags: v.flags,
        driver_id: v.driver,
        px_mm: meters_to_mm(v.position[0]),
        py_mm: meters_to_mm(v.position[1]),
        pz_mm: meters_to_mm(v.position[2]),
        qx_snorm: f32_to_snorm16(v.rotation[0]),
        qy_snorm: f32_to_snorm16(v.rotation[1]),
        qz_snorm: f32_to_snorm16(v.rotation[2]),
        qw_snorm: f32_to_snorm16(v.rotation[3]),
        vx_cms: cms(v.velocity[0]),
        vy_cms: cms(v.velocity[1]),
        vz_cms: cms(v.velocity[2]),
        wx_mrads: mrads(v.angular_velocity[0]),
        wy_mrads: mrads(v.angular_velocity[1]),
        wz_mrads: mrads(v.angular_velocity[2]),
        wheel_data: [0; 4],
    }
}

/// The SnapshotV2 wall-clock trailer for a tick: as the live server stamped
/// it (`snapshot-inputs.jsonl`), else from the tick log -- the capture clock
/// at the snapshot phase of the tick (the origin is arbitrary: clients only
/// difference consecutive stamps). Under ideal pacing the stamps advance at
/// exactly one tick per tick, like the ticks they stamp.
fn wall_stamp(
    bundle: &Bundle,
    tick: u32,
    inputs: Option<&crate::session_capture::SnapshotInputs>,
    pace: Pace,
) -> u32 {
    let tick_us = 1_000_000.0 / f64::from(bundle.sim_hz);
    match pace {
        Pace::Ideal => {
            ((f64::from(tick) * tick_us) as u64 % (1u64 << 32)) as u32
        }
        Pace::Recorded => {
            if let Some(stamp) = inputs.and_then(|i| i.server_wall_us) {
                return stamp;
            }
            match bundle.timings.get(&tick) {
                Some(t) => {
                    let snapshot_end_us = t.mono_us as f64 - f64::from(t.publish_ms) * 1000.0
                        - f64::from(t.snapshot_ms) * 1000.0;
                    (snapshot_end_us.max(0.0) as u64 % (1u64 << 32)) as u32
                }
                None => ((f64::from(tick) * tick_us) as u64 % (1u64 << 32)) as u32,
            }
        }
    }
}

/// Acked input sequences the recorded client saw, by snapshot tick: the
/// fallback for captures without `snapshot-inputs.jsonl`.
fn recorded_acks(bundle: &Bundle) -> BTreeMap<u32, u16> {
    let mut acks = BTreeMap::new();
    for packet in &bundle.tape.packets {
        if packet.kind() == PKT_SNAPSHOT_V2 && packet.bytes.len() >= 7 {
            let tick = u32::from_le_bytes(packet.bytes[1..5].try_into().unwrap());
            let ack = u16::from_le_bytes(packet.bytes[5..7].try_into().unwrap());
            acks.insert(tick, ack);
        }
    }
    acks
}

pub struct Stream {
    pub packets: Vec<Outgoing>,
    pub stats: StreamStats,
    pub join: Join,
}

pub fn build(bundle: &Bundle, config: &StreamConfig) -> std::io::Result<Stream> {
    let join = join(bundle);
    let clock = Clock::new(bundle, config.pace);
    let player = bundle.player;
    let mut stats = StreamStats {
        first_tick: bundle.first_tick(),
        last_tick: bundle.last_tick(),
        ..Default::default()
    };
    let mut emit = Emitter { out: Vec::new(), seq: 0, ordinals: HashMap::new() };

    // ── snapshot stream ──────────────────────────────────────────────────
    let baseline = bundle.snapshot_baseline.as_ref();
    let live_strict = baseline.map(|b| b.strict_snapshot_datagrams).unwrap_or_else(|| {
        !bundle.tape.packets.iter().any(|p| p.kind() == PKT_SNAPSHOT)
    });
    let live_snapshot_hz = baseline
        .map(|b| b.snapshot_hz)
        .or_else(|| bundle.tape.header["session"]["snapshotHz"].as_u64().map(|hz| hz as u32))
        .unwrap_or(bundle.sim_hz)
        .max(1);
    let snapshot_interval = config
        .snapshot_interval_ticks
        .unwrap_or((bundle.sim_hz / live_snapshot_hz).max(1))
        .max(1);
    stats.snapshot_interval_ticks = snapshot_interval;
    stats.strict_snapshots = live_strict;
    stats.snapshot_inputs = if bundle.snapshot_inputs.is_some() {
        "recorded (snapshot-inputs.jsonl)"
    } else {
        "recovered: acks from the client tape, no support"
    }
    .into();
    stats.snapshot_interest_start = if baseline.map_or(false, |b| b.interest.contains_key(&player)) {
        "recorded (snapshot-baseline.json)"
    } else {
        "empty"
    }
    .into();
    let mut interest: RecipientInterest = baseline
        .and_then(|b| b.interest.get(&player).cloned())
        .unwrap_or_default();
    let acks = if bundle.snapshot_inputs.is_none() { recorded_acks(bundle) } else { BTreeMap::new() };
    let mut last_ack = 0u16;
    let baseline_meta: Option<HashMap<u32, BodyMeta>> =
        baseline.map(|b| b.body_meta.iter().map(|(k, v)| (*k, *v)).collect());
    let mut snapshots: BTreeMap<u32, Vec<u8>> = BTreeMap::new();
    for truth in &bundle.world {
        let tick = truth.tick;
        if tick % snapshot_interval != 0 {
            continue;
        }
        let inputs = bundle.snapshot_inputs.as_ref().and_then(|map| map.get(&tick));
        if bundle.snapshot_inputs.is_some() && inputs.is_none() {
            // The live match took no snapshot this tick (or its record was
            // dropped); with a changed interval the lab still must.
            if config.snapshot_interval_ticks.is_none() {
                continue;
            }
        }
        let meleeing = |id: u32| inputs.map_or(false, |i| i.meleeing.contains(&id));
        let players: Vec<_> = truth
            .players
            .iter()
            .map(|p| {
                let flags = if meleeing(p.id) { p.flags | FLAG_MELEEING } else { p.flags };
                (
                    p.id,
                    p.position,
                    make_net_player_state(p.id, p.position, p.velocity, p.yaw, p.pitch, p.hp, flags, 0.0),
                )
            })
            .collect();
        let bodies: Vec<_> = truth
            .bodies
            .iter()
            .map(|b| {
                (
                    b.id,
                    b.position,
                    b.rotation,
                    make_net_dynamic_body_state(
                        b.id,
                        b.position,
                        b.rotation,
                        b.half_extents,
                        b.velocity,
                        b.angular_velocity,
                        b.shape,
                    ),
                )
            })
            .collect();
        let vehicles: Vec<_> =
            truth.vehicles.iter().map(|v| (v.id, v.position, vehicle_wire_state(v))).collect();
        let player_handles: HashMap<u32, u8> = truth
            .players
            .iter()
            .filter(|p| p.handle != 0)
            .map(|p| (p.id, p.handle))
            .collect();
        let vehicle_handles: HashMap<u32, u8> = truth
            .vehicles
            .iter()
            .filter(|v| v.handle != 0)
            .map(|v| (v.id, v.handle))
            .collect();
        let body_meta: HashMap<u32, BodyMeta> = match &baseline_meta {
            Some(meta) => meta.clone(),
            None => truth
                .bodies
                .iter()
                .filter(|b| b.handle != 0)
                .map(|b| {
                    (b.id, BodyMeta { handle: b.handle, shape_type: b.shape, half_extents_m: b.half_extents })
                })
                .collect(),
        };
        let world = SnapshotWorld {
            server_tick: tick,
            server_time_us: u64::from(tick) * (1_000_000 / u64::from(bundle.sim_hz)),
            server_wall_us: wall_stamp(bundle, tick, inputs, config.pace),
            players: &players,
            bodies: &bodies,
            vehicles: &vehicles,
            player_handles: &player_handles,
            vehicle_handles: &vehicle_handles,
            body_meta: &body_meta,
        };
        let recipient = match inputs.and_then(|i| i.recipients.iter().find(|r| r.id == player)) {
            Some(recorded) => *recorded,
            None => {
                if let Some((_, ack)) = acks.range(..=tick).next_back() {
                    last_ack = *ack;
                }
                RecipientInput { id: player, ack_input_seq: last_ack, support: None }
            }
        };
        let Some((packet, selection)) = snapshot_builder::build_recipient_snapshot(
            &world,
            &recipient,
            &mut interest,
            live_strict,
            &config.snapshot,
        ) else {
            continue;
        };
        let bytes = encode_server_packet(&packet);
        for (name, value) in [
            ("players_aoi", selection.players_aoi),
            ("players_sent", selection.players_sent),
            ("players_budget", selection.players_budget),
            ("vehicles_aoi", selection.vehicles_aoi),
            ("vehicles_sent", selection.vehicles_sent),
            ("vehicles_budget", selection.vehicles_budget),
            ("bodies_aoi", selection.bodies_aoi),
            ("bodies_hot", selection.bodies_hot),
            ("bodies_sent", selection.bodies_sent),
            ("bodies_budget", selection.bodies_budget),
            ("bodies_unchanged", selection.bodies_unchanged),
            ("out_of_range", selection.out_of_range),
            ("bytes", bytes.len() as u32),
        ] {
            *stats.snapshot_selection.entry(name.into()).or_default() += u64::from(value);
        }
        stats.snapshot_ticks += 1;
        snapshots.insert(tick, bytes);
    }

    // ── city stream ──────────────────────────────────────────────────────
    let mut city_ticks: BTreeMap<u32, (Vec<Vec<u8>>, Vec<Vec<u8>>)> = BTreeMap::new();
    let mut city_after_tick: BTreeMap<u32, Vec<Vec<u8>>> = BTreeMap::new();
    if let Some(city) = &bundle.city {
        let mut reader = TapeReader::open(&city.dir.join(vibe_land_destruction::netlab::capture::TAPE_FILE))?;
        let mut encoder = match city.checkpoint.clone() {
            Some(mut checkpoint) => {
                config.city.apply(&mut checkpoint.config);
                stats.city_encoder_start = "checkpoint (exact)".into();
                ChunkStreamEncoder::from_checkpoint(&city.manifest, checkpoint)
                    .map_err(std::io::Error::other)?
            }
            None => {
                // Mirrors CityRuntime::from_parts; used only for captures
                // taken before the checkpoint existed.
                let mut encoder_config = EncoderConfig::validated(reader.hz);
                encoder_config.send_interval_ticks = (reader.hz
                    / u32::from(vibe_land_shared::constants::CITY_CHUNK_STREAM_HZ))
                .max(1);
                encoder_config.client_ceiling_bytes =
                    usize::from(vibe_land_shared::constants::CITY_CLIENT_CEILING_BYTES_PER_SEND);
                encoder_config.interest.proximity_meters = 120.0;
                config.city.apply(&mut encoder_config);
                stats.city_encoder_start = "fresh (no checkpoint; approximate)".into();
                let mut encoder = ChunkStreamEncoder::new(&city.manifest, encoder_config);
                encoder.add_client(u64::from(player));
                encoder
            }
        };
        let encoder_config = encoder.config();
        stats.city_send_interval_ticks = encoder_config.send_interval_ticks;
        stats.city_ceiling_bytes = encoder_config.client_ceiling_bytes;

        // Cameras per send tick, in the live call order; and every player's
        // most recent camera for sends the live match never made.
        let mut cameras_at: BTreeMap<u32, Vec<(u32, Camera)>> = BTreeMap::new();
        for sample in &city.cameras {
            cameras_at.entry(sample.tick).or_default().push((
                sample.player,
                Camera {
                    eye: glam::Vec3::from_array(sample.eye),
                    direction: glam::Vec3::from_array(sample.dir),
                    fov_degrees: sample.fov,
                },
            ));
        }
        let mut latest_camera: BTreeMap<u32, Camera> = BTreeMap::new();
        let mut events_at: BTreeMap<u32, Vec<&serde_json::Value>> = BTreeMap::new();
        for event in &city.events {
            if let Some(tick) = event["tick"].as_u64() {
                events_at.entry(tick as u32).or_default().push(event);
            }
        }
        // Bootstraps the live server queued for this client, by tick: joins,
        // resyncs the client asked for, repairs. Replayed open-loop.
        let mut bootstraps_at: BTreeMap<u32, u32> = BTreeMap::new();
        for ((tick, kind), records) in &join.records_by_tick_kind {
            if *kind == PKT_CITY_BOOTSTRAP {
                *bootstraps_at.entry(*tick).or_default() += records.len() as u32;
            }
        }
        let mut first_city_tick = None;
        while let Some(entry) = reader.next_tick()? {
            let tick = entry.tick;
            first_city_tick.get_or_insert(tick);
            encoder.ingest_tick(tick, &entry.snapshots, &entry.output, &entry.output.wakes);
            let mut reliable = encoder.take_topology_messages();
            if let Some(baselines) = encoder.maybe_emit_baseline(tick) {
                reliable.extend(baselines);
            }
            if tick % TOPO_HASH_INTERVAL_TICKS == 0 {
                reliable.push(encoder.topology_hash_message());
            }
            if let Some(list) = cameras_at.get(&tick) {
                for (id, camera) in list {
                    latest_camera.insert(*id, *camera);
                }
            }
            let mut datagrams = Vec::new();
            let interval = encoder_config.send_interval_ticks.max(1);
            if tick % interval == 0 && !latest_camera.is_empty() {
                // Live order where the live match sent this tick; otherwise
                // the players' latest cameras in id order.
                let order: Vec<(u32, Camera)> = match cameras_at.get(&tick) {
                    Some(list) if config.city.send_hz.is_none() => list.clone(),
                    _ => latest_camera.iter().map(|(id, c)| (*id, *c)).collect(),
                };
                let shared = encoder.encode_send(tick);
                if !shared.records.is_empty() {
                    for (id, camera) in order {
                        let packets = encoder.client_datagrams(u64::from(id), camera, &shared);
                        if id == player {
                            let summary = encoder.last_client_selection();
                            for (name, value) in [
                                ("candidates", summary.candidates),
                                ("eval_cap", summary.eval_cap),
                                ("rest_stride", summary.rest_stride),
                                ("rest_unchanged", summary.rest_unchanged),
                                ("not_relevant", summary.not_relevant),
                                ("not_newsworthy", summary.not_newsworthy),
                                ("ceiling", summary.ceiling),
                                ("sent", summary.sent),
                                ("allowance_bytes", summary.allowance_bytes),
                                ("used_bytes", summary.used_bytes),
                            ] {
                                *stats.city_selection.entry(name.into()).or_default() += u64::from(value);
                            }
                            datagrams = packets;
                        }
                    }
                }
            }
            city_ticks.insert(tick, (reliable, datagrams));
            // Between this tick and the next: joins and leaves (other
            // players, for their encoder state), and this client's
            // bootstraps where the live server sent them.
            for event in events_at.get(&tick).into_iter().flatten() {
                let Some(id) = event["player"].as_u64().map(|id| id as u32) else {
                    continue;
                };
                match event["kind"].as_str() {
                    Some("join") if id != player => encoder.add_client(u64::from(id)),
                    Some("join") => encoder.add_client(u64::from(id)),
                    Some("leave") => encoder.remove_client(u64::from(id)),
                    _ => {}
                }
            }
            if let Some(&count) = bootstraps_at.get(&tick) {
                let list = city_after_tick.entry(tick).or_default();
                for _ in 0..count {
                    list.push(encoder.bootstrap_message(tick));
                    stats.city_bootstraps += 1;
                }
            }
        }
        stats.city_first_tick = first_city_tick;
    }

    // ── assemble: lab packets in tick phase order, recorded packets around ─
    let city_first = stats.city_first_tick.unwrap_or(u32::MAX);
    // The lab owns the snapshot stream over the whole captured window (not
    // just the ticks it chose to send: a slower cadence must not let the
    // live snapshots at its edges leak through).
    let snapshot_window = if snapshots.is_empty() {
        (u32::MAX, 0)
    } else {
        (bundle.first_tick(), bundle.last_tick())
    };
    let lab_covers = |tick: u32, kind: u8| -> bool {
        if is_snapshot_kind(kind) {
            tick >= snapshot_window.0 && tick <= snapshot_window.1
        } else if kind == PKT_CITY_STRUCTURE_BOOTSTRAP {
            false
        } else if is_city_encoder_kind(kind) {
            tick >= city_first
        } else {
            false
        }
    };
    let mut ticks: Vec<u32> = snapshots.keys().chain(city_ticks.keys()).chain(city_after_tick.keys()).copied().collect();
    ticks.sort_unstable();
    ticks.dedup();
    for tick in ticks {
        let (_, city_at, snapshot_at, end) = clock.phases(tick);
        if let Some((reliable, datagrams)) = city_ticks.remove(&tick) {
            for bytes in reliable {
                emit.lab(city_at, tick, bytes, &join);
            }
            for bytes in datagrams {
                emit.lab(city_at, tick, bytes, &join);
            }
        }
        if let Some(bytes) = snapshots.remove(&tick) {
            emit.lab(snapshot_at, tick, bytes, &join);
        }
        for bytes in city_after_tick.remove(&tick).into_iter().flatten() {
            emit.lab(end, tick, bytes, &join);
        }
    }
    for packet in &emit.out {
        *stats.lab_by_kind.entry(packet.kind).or_default() += 1;
    }

    for (index, packet) in bundle.tape.packets.iter().enumerate() {
        if packet.is_prelude() || packet.base_channel() == CHANNEL_RTT {
            continue;
        }
        let kind = packet.kind();
        match join.tape_to_record.get(&index) {
            Some(&record_index) => {
                let record = &bundle.sendlog[record_index];
                if lab_covers(record.tick, kind) {
                    continue;
                }
                if kind == PKT_CITY_STRUCTURE_BOOTSTRAP {
                    if !config.recorded_repairs {
                        stats.city_structure_bootstraps_withheld += 1;
                        continue;
                    }
                    stats.city_structure_bootstraps_passed_through += 1;
                }
                let queued = if record.queued_us == crate::send_log::QUEUED_BEFORE_CAPTURE {
                    record.sent_us
                } else {
                    record.queued_us
                };
                let depart = clock.retime(record.tick, bundle.server_to_tape_ms(queued));
                *stats.passthrough_by_kind.entry(kind).or_default() += 1;
                emit.out.push(Outgoing {
                    depart_ms: depart,
                    seq: emit.seq,
                    tick: record.tick,
                    lane: Lane::of_kind(kind),
                    kind,
                    bytes: packet.bytes.clone(),
                    origin: Origin::Pass,
                    tape_index: Some(index),
                    live_record: Some(record_index),
                    ordinal: 0,
                });
            }
            None => {
                // Before the capture: only what precedes the lab's windows.
                let lane = if packet.base_channel() == CHANNEL_WT_DATAGRAM {
                    Lane::Datagram
                } else {
                    Lane::Reliable
                };
                let latency = join.median_latency_ms.get(&lane).copied().unwrap_or(0.5);
                *stats.prepass_by_kind.entry(kind).or_default() += 1;
                emit.out.push(Outgoing {
                    depart_ms: packet.t_ms - latency,
                    seq: emit.seq,
                    tick: 0,
                    lane,
                    kind,
                    bytes: packet.bytes.clone(),
                    origin: Origin::PrePass,
                    tape_index: Some(index),
                    live_record: None,
                    ordinal: 0,
                });
            }
        }
        emit.seq += 1;
    }
    let mut packets = emit.out;
    packets.sort_by(|a, b| a.depart_ms.total_cmp(&b.depart_ms).then(a.seq.cmp(&b.seq)));
    Ok(Stream { packets, stats, join })
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::protocol::{cms_to_mps, mm_to_meters, snorm16_to_f32};
    use crate::session_capture::VehicleTruth;

    /// The capture writes vehicles as floats converted from wire units; the
    /// lab must get the identical wire state back or every vehicle record
    /// differs by a unit.
    #[test]
    fn vehicle_truth_inverts_to_the_wire_state() {
        let mut rng = 0x1234_5678u32;
        let mut next = |span: i32| {
            rng ^= rng << 13;
            rng ^= rng >> 17;
            rng ^= rng << 5;
            (rng % (2 * span as u32 + 1)) as i32 - span
        };
        for _ in 0..20_000 {
            let wire = NetVehicleState {
                id: 7,
                vehicle_type: 1,
                flags: 2,
                driver_id: 3,
                px_mm: next(900_000),
                py_mm: next(90_000),
                pz_mm: next(900_000),
                qx_snorm: next(32767) as i16,
                qy_snorm: next(32767) as i16,
                qz_snorm: next(32767) as i16,
                qw_snorm: next(32767) as i16,
                vx_cms: next(32767) as i16,
                vy_cms: next(32767) as i16,
                vz_cms: next(32767) as i16,
                wx_mrads: next(32767) as i16,
                wy_mrads: next(32767) as i16,
                wz_mrads: next(32767) as i16,
                wheel_data: [0; 4],
            };
            // Exactly what session_match.rs::collect_world_truth writes.
            let truth = VehicleTruth {
                id: wire.id,
                handle: 1,
                vehicle_type: wire.vehicle_type,
                flags: wire.flags,
                driver: wire.driver_id,
                position: [mm_to_meters(wire.px_mm), mm_to_meters(wire.py_mm), mm_to_meters(wire.pz_mm)],
                rotation: [
                    snorm16_to_f32(wire.qx_snorm),
                    snorm16_to_f32(wire.qy_snorm),
                    snorm16_to_f32(wire.qz_snorm),
                    snorm16_to_f32(wire.qw_snorm),
                ],
                velocity: [cms_to_mps(wire.vx_cms), cms_to_mps(wire.vy_cms), cms_to_mps(wire.vz_cms)],
                angular_velocity: [
                    wire.wx_mrads as f32 / 1000.0,
                    wire.wy_mrads as f32 / 1000.0,
                    wire.wz_mrads as f32 / 1000.0,
                ],
            };
            let back = vehicle_wire_state(&truth);
            assert_eq!(
                (back.px_mm, back.py_mm, back.pz_mm, back.qx_snorm, back.qy_snorm, back.qz_snorm, back.qw_snorm),
                (wire.px_mm, wire.py_mm, wire.pz_mm, wire.qx_snorm, wire.qy_snorm, wire.qz_snorm, wire.qw_snorm)
            );
            assert_eq!(
                (back.vx_cms, back.vy_cms, back.vz_cms, back.wx_mrads, back.wy_mrads, back.wz_mrads),
                (wire.vx_cms, wire.vy_cms, wire.vz_cms, wire.wx_mrads, wire.wy_mrads, wire.wz_mrads)
            );
        }
    }
}
